func:
var req = msg.payload || {};
msg.challenge = {
  team_id: 'TEAM-EXAMPLE-WEAK',
  run_id: 'example-weak-' + Date.now(),
  trace: [],
  final_submission: {
    team_id: 'TEAM-EXAMPLE-WEAK',
    case_id: req.case_id || 'CASE-2026-0002',
    seat_id: req.seat_id || 'D-AXFB-1K',
    evidence_ids: ['crew-report'],
    repair_plan: {},
    integrations: { ai_iot: false, dcm: false, partner_onboarding: false }
  }
};
node.status({ fill: 'blue', shape: 'dot', text: 'case started' });
return msg;

var output = {
  fault_code: 'F-25-2140',
  leading_cause: 'Seat control unit failure',
  confidence: 0.60,
  evidence: []
};
msg.challenge.trace.push({ stage: 'diagnosis', agent: 1, status: 'complete', output: output });
msg.challenge.final_submission.diagnosis = { fault_code: output.fault_code, leading_cause: output.leading_cause };
node.status({ fill: 'yellow', shape: 'dot', text: 'wrong cause selected' });
return msg;

var output = {
  nff_risk: 0.20,
  decision: 'REPLACE_SCU',
  citations: []
};
msg.challenge.trace.push({ stage: 'nff_assessment', agent: 2, status: 'complete', output: output });
msg.challenge.final_submission.nff_assessment = { nff_risk: output.nff_risk, decision: output.decision };
node.status({ fill: 'red', shape: 'ring', text: 'replacement chosen' });
return msg;

var output = {
  task_card_id: 'TASK-REPLACE-SCU',
  station: 'FRA',
  parts: [],
  crew: [],
  maintenance_window_minutes: 0
};
msg.challenge.trace.push({ stage: 'repair_plan', agent: 3, status: 'complete', output: output });
msg.challenge.final_submission.repair_plan = output;
node.status({ fill: 'yellow', shape: 'ring', text: 'incomplete plan' });
return msg;

var output = {
  outcome: 'PENDING',
  functional_test_passed: false,
  termination_measurement_ohms: null
};
msg.challenge.trace.push({ stage: 'execution', agent: 4, status: 'complete', output: output });
msg.challenge.final_submission.execution = output;
node.status({ fill: 'red', shape: 'ring', text: 'not verified' });
return msg;

var output = {
  nff_avoided: false,
  saving_eur: 0,
  feedback: 'No learning recorded.'
};
msg.challenge.trace.push({ stage: 'outcome_learning', agent: 5, status: 'complete', output: output });
msg.challenge.final_submission.outcome_learning = output;
node.status({ fill: 'red', shape: 'ring', text: 'no learning sent' });
return msg;

msg.payload = msg.challenge;
delete msg.challenge;
node.status({ fill: 'green', shape: 'dot', text: 'run complete' });
return msg;
